// friday13.cs — Friday the 13th experiments with the proleptic Gregorian calendar

// 1. Find the earliest Friday the 13th starting from 0001-01-01
var date = new DateTime(1, 1, 13); // start on the 13th of January, year 1
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd} ({date.DayOfWeek})");

// 2. Count Friday the 13ths in a full 400-year cycle (years 1–400)
int count = 0;
var cycleStart = new DateTime(1, 1, 13);
var cycleEnd = new DateTime(401, 1, 1);
var d = cycleStart;
while (d < cycleEnd)
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        count++;
    d = d.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// 3. Bonus: distribution by day-of-week for the 13th
Console.WriteLine("\nDay-of-week distribution for the 13th (400-year cycle):");
var tally = new int[7];
d = cycleStart;
while (d < cycleEnd)
{
    tally[(int)d.DayOfWeek]++;
    d = d.AddMonths(1);
}
foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {dow,-10} {tally[(int)dow],4}");

